15	func writeJSON(w http.ResponseWriter, status int, v any) {
16		w.Header().Set("Content-Type", "application/json")
17		w.WriteHeader(status)
18		_ = json.NewEncoder(w).Encode(v)
19	}
20	
21	// writeError answers {"error": code, "message": message}.
22	func writeError(w http.ResponseWriter, status int, code, message string) {
23		writeJSON(w, status, map[string]string{"error": code, "message": message})
24	}
25	
26	// decode reads a JSON body (at most 1 MiB) into v, or answers 400 and returns false.
27	func decode(w http.ResponseWriter, r *http.Request, v any) bool {
28		dec := json.NewDecoder(io.LimitReader(r.Body, 1<<20))
29		if err := dec.Decode(v); err != nil {
30			writeError(w, http.StatusBadRequest, "invalid_json", "the body is not valid JSON: "+err.Error())
31			return false
32		}
33		return true
34	}
35	
36	// storeError answers for an error from the store or a service.
37	func (s *Server) storeError(w http.ResponseWriter, err error) {
38		switch {
39		case errors.Is(err, store.ErrNotFound):
40			writeError(w, http.StatusNotFound, "not_found", "no such object")
41		case errors.Is(err, store.ErrEmailTaken):
42			writeError(w, http.StatusConflict, "email_taken", err.Error())
43		case errors.Is(err, store.ErrAlreadyMember):
44			writeError(w, http.StatusConflict, "already_member", err.Error())
45		case errors.Is(err, store.ErrConflict):
46			writeError(w, http.StatusConflict, "conflict", err.Error())
47		case errors.Is(err, store.ErrCustomerOrgMismatch):
48			writeError(w, http.StatusUnprocessableEntity, "customer_org_mismatch", err.Error())
49		case errors.Is(err, store.ErrInvalid):
50			writeError(w, http.StatusUnprocessableEntity, "invalid", err.Error())
51		default:
52			s.log.Error("request failed", "err", err)
53			writeError(w, http.StatusInternalServerError, "internal", "something went wrong")
54		}
55	}
56	
57	// list is the shape of every list response. NextCursor is set when there is another page.
58	type list struct {
59		Items      any    `json:"items"`
60		NextCursor string `json:"next_cursor,omitempty"`
61	}
62	
63	// page is a request for one page of a list: ?limit= (1 to 100, default 20) and ?cursor= (from the previous page).
64	type page struct {
65		limit int
66		after *cursor
67	}
68	
69	// cursor is where a page starts: after the item with this creation time and ID.
70	type cursor struct {
71		T  time.Time `json:"t"`
72		ID string    `json:"id"`
73	}
74	
75	func (c cursor) less(o cursor) bool {
76		if !c.T.Equal(o.T) {
77			return c.T.Before(o.T)
78		}
79		return c.ID < o.ID
80	}
81	
82	// parsePage reads ?limit and ?cursor, or answers 400 and returns false.
83	func parsePage(w http.ResponseWriter, r *http.Request) (page, bool) {
84		p := page{limit: 20}
85		if v := r.URL.Query().Get("limit"); v != "" {
86			n, err := strconv.Atoi(v)
87			if err != nil || n < 1 || n > 100 {
88				writeError(w, http.StatusBadRequest, "invalid_limit", "limit is a whole number from 1 to 100")
89				return page{}, false
90			}
91			p.limit = n
92		}
93		if v := r.URL.Query().Get("cursor"); v != "" {
94			b, err := base64.RawURLEncoding.DecodeString(v)
95			var c cursor
96			if err != nil || json.Unmarshal(b, &c) != nil || c.ID == "" {
97				writeError(w, http.StatusBadRequest, "invalid_cursor", "the cursor is not one this API gave out")
98				return page{}, false
99			}
100			p.after = &c
101		}
102		return p, true
103	}
104	
105	func encodeCursor(c cursor) string {
106		b, _ := json.Marshal(c)
107		return base64.RawURLEncoding.EncodeToString(b)
108	}
109	
110	// pageOf returns one page of items, which are sorted by key (creation time, then ID), and the cursor of the next page.
111	func pageOf[T any](items []T, key func(T) cursor, p page) ([]T, string) {
112		start := 0
113		if p.after != nil {
114			start = len(items)
115			for i, it := range items {
116				if p.after.less(key(it)) {
117					start = i
118					break
119				}
120			}
121		}
122		end := min(start+p.limit, len(items))
123		out := items[start:end]
124		next := ""
125		if end < len(items) && len(out) > 0 {
126			next = encodeCursor(key(out[len(out)-1]))
127		}
128		return out, next
129	}
