12	// CreatePlan adds a plan. UsageType defaults to Licensed; a new plan is active.
13	func (s *Store) CreatePlan(p Plan, now time.Time) (Plan, error) {
14		p.Name = strings.TrimSpace(p.Name)
15		if p.UsageType == "" {
