package store

import "time"

// IdempotencyTTL is how long a kept answer is replayed.
const IdempotencyTTL = 24 * time.Hour

type idempotencyKey struct{ org, key string }

// IdempotencyRecord is a request that was sent with an Idempotency-Key: what it was for, and, once it was answered, the
// answer. Done is false while the request is still being handled.
type IdempotencyRecord struct {
	InvoiceID   string
	Fingerprint string // of the request body
	Done        bool
	Status      int
	Body        []byte
	CompletedAt time.Time
}

// ClaimIdempotencyKey records rec as the request that uses key in the organization. It returns true when the key was free:
// the key was never used, or its kept answer is older than IdempotencyTTL. Otherwise it returns the key's record and false,
// and the caller decides what to answer.
func (s *Store) ClaimIdempotencyKey(orgID, key string, rec IdempotencyRecord, now time.Time) (IdempotencyRecord, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	k := idempotencyKey{orgID, key}
	if old, ok := s.idempotency[k]; ok && (!old.Done || now.Before(old.CompletedAt.Add(IdempotencyTTL))) {
		return old, false
	}
	s.idempotency[k] = rec
	return rec, true
}

// FinishIdempotencyKey keeps the answer to the request that claimed key.
func (s *Store) FinishIdempotencyKey(orgID, key string, status int, body []byte, now time.Time) {
	s.mu.Lock()
	defer s.mu.Unlock()
	k := idempotencyKey{orgID, key}
	rec := s.idempotency[k]
	rec.Done, rec.Status, rec.Body, rec.CompletedAt = true, status, append([]byte(nil), body...), now.UTC()
	s.idempotency[k] = rec
}

// ReleaseIdempotencyKey frees key when the request that claimed it has no answer to keep, so that a retry runs again.
func (s *Store) ReleaseIdempotencyKey(orgID, key string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	k := idempotencyKey{orgID, key}
	if rec, ok := s.idempotency[k]; ok && !rec.Done {
		delete(s.idempotency, k)
	}
}

