package api_test

import (
	"net/http"
	"strings"
	"sync"
	"testing"
	"time"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/payments"
	"example.com/tally/internal/store"
)

// newInvoice creates an open invoice of 10.00 for a new customer with this email, through the API.
func newInvoice(e *apitest.Env, org apitest.Org, email string) store.Invoice {
	e.T.Helper()
	c := e.CreateCustomer(org, "Jane", email)
	var inv store.Invoice
	e.MustDo(http.StatusCreated, "POST", "/v1/invoices", org.Key, map[string]any{"customer_id": c.ID, "currency": "USD",
		"lines": []map[string]any{{"description": "Consulting", "quantity": 1, "unit_amount": 1000}}}, &inv)
	return inv
}

// payKeyed pays an invoice with an Idempotency-Key.
func payKeyed(e *apitest.Env, org apitest.Org, invoiceID, key string, body any) *apitest.Response {
	e.T.Helper()
	return e.DoWith("POST", "/v1/invoices/"+invoiceID+"/pay", org.Key, body, http.Header{"Idempotency-Key": {key}})
}

var visa = map[string]string{"payment_method": "pm_card_visa"}

func TestPayWithKeyReplaysFirstAnswer(t *testing.T) {
	e := apitest.New(t)
	inv := newInvoice(e, e.Acme, "jane@example.com")
	first := payKeyed(e, e.Acme, inv.ID, "pay-1", visa)
	if first.Code != http.StatusOK || first.Header.Get("Idempotent-Replayed") != "" {
		t.Fatalf("first: %s", first)
	}
	again := payKeyed(e, e.Acme, inv.ID, "pay-1", visa)
	if again.Code != first.Code || string(again.Body) != string(first.Body) || again.Header.Get("Idempotent-Replayed") != "true" {
		t.Fatalf("retry = %s, want the first answer %s", again, first)
	}
	if n := len(e.Gateway.Charges()); n != 1 {
		t.Fatalf("%d charges", n)
	}
}

func TestPayWithKeyKeepsDeclines(t *testing.T) {
	e := apitest.New(t)
	inv := newInvoice(e, e.Acme, "jane@example.com")
	declined := map[string]string{"payment_method": "pm_card_declined"}
	first := payKeyed(e, e.Acme, inv.ID, "pay-1", declined)
	if first.Code != http.StatusPaymentRequired {
		t.Fatalf("first: %s", first)
	}
	again := payKeyed(e, e.Acme, inv.ID, "pay-1", declined)
	if again.Code != http.StatusPaymentRequired || string(again.Body) != string(first.Body) || again.Header.Get("Idempotent-Replayed") != "true" {
		t.Fatalf("retry = %s, want the first answer %s", again, first)
	}
	if n := len(e.Gateway.Calls()); n != 1 {
		t.Fatalf("the gateway got %d requests", n)
	}
}

func TestPayWithKeyTriesAgainAfterServerError(t *testing.T) {
	e := apitest.New(t)
	inv := newInvoice(e, e.Acme, "jane@example.com")
	down := map[string]string{"payment_method": "pm_gateway_down"}
	if r := payKeyed(e, e.Acme, inv.ID, "pay-1", down); r.Code != http.StatusServiceUnavailable || r.Map(t)["error"] != "gateway_unavailable" {
		t.Fatalf("first: %s", r)
	}
	r := payKeyed(e, e.Acme, inv.ID, "pay-1", down)
	if r.Code != http.StatusServiceUnavailable || r.Header.Get("Idempotent-Replayed") != "" {
		t.Fatalf("retry = %s, want the payment to be tried again", r)
	}
	if n := len(e.Gateway.Calls()); n != 2 {
		t.Fatalf("the gateway got %d requests, want 2", n)
	}
}

func TestIdempotencyKeysBelongToAnOrganization(t *testing.T) {
	e := apitest.New(t)
	acme := newInvoice(e, e.Acme, "jane@acme.example")
	globex := newInvoice(e, e.Globex, "jane@globex.example")
